'use strict';
/* ---------------------------------------------------------------------------
 * util.js - shared helpers, pre-rendered textures, text drawing.
 * All art and audio in this project is generated by code; no external assets.
 * ------------------------------------------------------------------------- */
const FNAF = window.FNAF = {};
FNAF.W = 1280;
FNAF.H = 720;

FNAF.rand = (a, b) => a + Math.random() * (b - a);
FNAF.randInt = (a, b) => Math.floor(a + Math.random() * (b - a + 1));
FNAF.chance = p => Math.random() < p;
FNAF.pick = arr => arr[Math.floor(Math.random() * arr.length)];
FNAF.clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
FNAF.lerp = (a, b, t) => a + (b - a) * t;
FNAF.smooth = t => t * t * (3 - 2 * t);
FNAF.inRect = (px, py, r) => px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h;

FNAF.makeCanvas = (w, h) => {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
};

/* Deterministic pseudo-random for stable textures */
FNAF.seeded = seed => {
  let s = (seed >>> 0) || 1;
  return () => {
    s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0;
    return s / 4294967296;
  };
};

FNAF.FONT = '"Consolas","Lucida Console","Courier New",monospace';
FNAF.FONT_TITLE = '"Impact","Arial Black","Franklin Gothic Medium",sans-serif';
FNAF.FONT_SERIF = '"Georgia","Times New Roman",serif';

FNAF.font = (size, bold, family) => (bold ? 'bold ' : '') + size + 'px ' + (family || FNAF.FONT);

FNAF.text = (ctx, str, x, y, o) => {
  o = o || {};
  ctx.save();
  ctx.font = o.font || FNAF.font(o.size || 20, o.bold, o.family);
  ctx.textAlign = o.align || 'left';
  ctx.textBaseline = o.baseline || 'top';
  if (o.alpha !== undefined) ctx.globalAlpha = o.alpha;
  if (o.shadow) {
    ctx.shadowColor = o.shadow;
    ctx.shadowBlur = o.shadowBlur || 8;
  }
  if (o.stroke) {
    ctx.lineWidth = o.strokeWidth || 3;
    ctx.strokeStyle = o.stroke;
    ctx.strokeText(str, x, y);
  }
  ctx.fillStyle = o.color || '#fff';
  ctx.fillText(str, x, y);
  ctx.restore();
};

/* Draw wrapped text; returns the y after the last line */
FNAF.wrapText = (ctx, str, x, y, maxW, lineH, o) => {
  o = o || {};
  ctx.save();
  ctx.font = o.font || FNAF.font(o.size || 18, o.bold, o.family);
  const paragraphs = String(str).split('\n');
  let cy = y;
  for (const para of paragraphs) {
    const words = para.split(' ');
    let line = '';
    for (let i = 0; i < words.length; i++) {
      const test = line ? line + ' ' + words[i] : words[i];
      if (ctx.measureText(test).width > maxW && line) {
        FNAF.text(ctx, line, x, cy, o);
        line = words[i];
        cy += lineH;
      } else line = test;
    }
    FNAF.text(ctx, line, x, cy, o);
    cy += lineH;
  }
  ctx.restore();
  return cy;
};

FNAF.roundRect = (ctx, x, y, w, h, r) => {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
};

FNAF.ellipse = (ctx, cx, cy, rx, ry, rot) => {
  ctx.beginPath();
  ctx.ellipse(cx, cy, Math.max(0.1, rx), Math.max(0.1, ry), rot || 0, 0, Math.PI * 2);
  ctx.closePath();
};

FNAF.poly = (ctx, pts) => {
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
  ctx.closePath();
};

/* Shaded sphere-ish fill helper */
FNAF.shade = (ctx, cx, cy, r, base, hi, lo) => {
  const g = ctx.createRadialGradient(cx - r * 0.35, cy - r * 0.35, r * 0.1, cx, cy, r * 1.1);
  g.addColorStop(0, hi);
  g.addColorStop(0.5, base);
  g.addColorStop(1, lo);
  return g;
};

FNAF.hexToRgb = hex => {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};
FNAF.rgbStr = (rgb, a) => `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${a === undefined ? 1 : a})`;
FNAF.mix = (hexA, hexB, t) => {
  const a = FNAF.hexToRgb(hexA), b = FNAF.hexToRgb(hexB);
  return FNAF.rgbStr([Math.round(a[0] + (b[0] - a[0]) * t), Math.round(a[1] + (b[1] - a[1]) * t), Math.round(a[2] + (b[2] - a[2]) * t)]);
};
FNAF.darken = (hex, t) => FNAF.mix(hex, '#000000', t);
FNAF.lighten = (hex, t) => FNAF.mix(hex, '#ffffff', t);

/* ------------------------------------------------------------------ textures */
FNAF.tex = {};

FNAF.buildTextures = () => {
  const T = FNAF.tex;
  // TV static frames (low-res, drawn scaled with smoothing off)
  T.noise = [];
  for (let f = 0; f < 10; f++) {
    const c = FNAF.makeCanvas(320, 180);
    const ctx = c.getContext('2d');
    const img = ctx.createImageData(320, 180);
    const d = img.data;
    for (let i = 0; i < d.length; i += 4) {
      const v = Math.random() * 255 | 0;
      d[i] = d[i + 1] = d[i + 2] = v;
      d[i + 3] = 255;
    }
    ctx.putImageData(img, 0, 0);
    T.noise.push(c);
  }
  // Fine film grain (sparse dots) used over everything
  T.grain = [];
  for (let f = 0; f < 6; f++) {
    const c = FNAF.makeCanvas(640, 360);
    const ctx = c.getContext('2d');
    const img = ctx.createImageData(640, 360);
    const d = img.data;
    for (let i = 0; i < d.length; i += 4) {
      const v = Math.random() * 255 | 0;
      d[i] = d[i + 1] = d[i + 2] = v;
      d[i + 3] = Math.random() < 0.35 ? (Math.random() * 60 | 0) : 0;
    }
    ctx.putImageData(img, 0, 0);
    T.grain.push(c);
  }
  // Scanlines
  {
    const c = FNAF.makeCanvas(4, FNAF.H);
    const ctx = c.getContext('2d');
    ctx.fillStyle = 'rgba(0,0,0,0.22)';
    for (let y = 0; y < FNAF.H; y += 3) ctx.fillRect(0, y, 4, 1);
    T.scanlines = c;
  }
  // Vignette
  {
    const c = FNAF.makeCanvas(FNAF.W, FNAF.H);
    const ctx = c.getContext('2d');
    const g = ctx.createRadialGradient(FNAF.W / 2, FNAF.H / 2, FNAF.H * 0.35, FNAF.W / 2, FNAF.H / 2, FNAF.W * 0.72);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(1, 'rgba(0,0,0,0.85)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, FNAF.W, FNAF.H);
    T.vignette = c;
  }
  // Dirt / smudge overlay for cameras
  {
    const c = FNAF.makeCanvas(FNAF.W, FNAF.H);
    const ctx = c.getContext('2d');
    const rnd = FNAF.seeded(1234);
    for (let i = 0; i < 140; i++) {
      const x = rnd() * FNAF.W, y = rnd() * FNAF.H, r = 10 + rnd() * 80;
      const g = ctx.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, `rgba(255,255,255,${0.02 + rnd() * 0.04})`);
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }
    T.smudge = c;
  }
  // Paper texture
  {
    const c = FNAF.makeCanvas(512, 512);
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#e9e1cf';
    ctx.fillRect(0, 0, 512, 512);
    const img = ctx.getImageData(0, 0, 512, 512);
    const d = img.data;
    const rnd = FNAF.seeded(77);
    for (let i = 0; i < d.length; i += 4) {
      const v = (rnd() - 0.5) * 26;
      d[i] += v; d[i + 1] += v; d[i + 2] += v * 0.8;
    }
    ctx.putImageData(img, 0, 0);
    T.paper = c;
  }
};

FNAF.drawNoise = (ctx, alpha, x, y, w, h) => {
  const frames = FNAF.tex.noise;
  const f = frames[(performance.now() / 40 | 0) % frames.length];
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(f, x || 0, y || 0, w || FNAF.W, h || FNAF.H);
  ctx.restore();
};

FNAF.drawGrain = (ctx, alpha) => {
  const frames = FNAF.tex.grain;
  const f = frames[(performance.now() / 50 | 0) % frames.length];
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(f, 0, 0, FNAF.W, FNAF.H);
  ctx.restore();
};

FNAF.drawScanlines = (ctx, alpha) => {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.drawImage(FNAF.tex.scanlines, 0, 0, FNAF.W, FNAF.H);
  ctx.restore();
};

/* Simple timer helper */
FNAF.Timer = class {
  constructor(interval) { this.interval = interval; this.t = 0; }
  tick(dt) { this.t += dt; if (this.t >= this.interval) { this.t -= this.interval; return true; } return false; }
  reset() { this.t = 0; }
};

/* Save data */
FNAF.SAVE_KEY = 'fnaf_web_save_v1';
FNAF.loadSave = () => {
  const def = { night: 1, beat5: false, beat6: false, beat420: false, captions: true, volume: 0.8 };
  try {
    const raw = localStorage.getItem(FNAF.SAVE_KEY);
    if (!raw) return def;
    return Object.assign(def, JSON.parse(raw));
  } catch (e) { return def; }
};
FNAF.storeSave = data => {
  try { localStorage.setItem(FNAF.SAVE_KEY, JSON.stringify(data)); } catch (e) { /* private mode */ }
};
